      ro: ["Cel mai înalt vârf din lanțul Cascade.", "Un vulcan activ.", "Puternic glaciat.", "Un parc național înconjoară muntele."],
      en: ["Highest peak in the Cascade Range.", "An active volcano.", "Heavily glaciated.", "A national park surrounds the mountain."],
      es: ["Cima más alta de la Cordillera de las Cascadas.", "Un volcán activo.", "Fuertemente glaciado.", "Un parque nacional rodea la montaña."],
      pt: ["Pico mais alto da cordilheira Cascade.", "Um vulcão ativo.", "Fortemente glacial.", "Um parque nacional circunda a montanha."],
      fr: ["Plus haut sommet de la chaîne des Cascades.", "Un volcan actif.", "Fortement englacé.", "Un parc national entoure la montagne."],
