      ro: ["O pădure națională din Idaho și Utah, numită după Munții Sawtooth zimțați.", "Se afla pe teritoriul Statelor Unite ale Americii.", "Are un rol in identitatea regionala intre coasta de est si cea de vest."],
      en: ["Encompasses over 2.1 million acres in highly remote central Idaho.", "Features the deeply jagged, massive granite peaks of the Sawtooth Range.", "Contains the highly critical, massive headwaters of the Salmon River.", "Protects over 300 massive, pristine high-elevation alpine lakes.", "A deeply crucial habitat for returning anadromous sockeye salmon.", "Established by an absolute massive proclamation by President Theodore Roosevelt."],
      es: ["Centro económico central de la región.", "Importante nudo de transporte y logística.", "Fuerte identidad cultural a través de museos locales.", "Crecimiento demográfico continuo durante décadas.", "Enfoques innovadores en el desarrollo urbano.", "Diversas oportunidades para actividades al aire libre.", "Compromiso con proyectos de sostenibilidad ecológica."],
      pt: ["Centro económico central da região.", "Importante nó de transporte e logística.", "Forte identidade cultural através de museus locais.", "Crescimento populacional contínuo ao longo de décadas.", "Abordagens inovadoras no desenvolvimento urbano.", "Diversas oportunidades para atividades ao ar livre.", "Compromisso com projetos de sustentabilidade ecológica."],
      fr: ["Centre économique central de la région.", "Nœud important pour le transport et la logistique.", "Forte identité culturelle grâce aux musées locaux.", "Croissance démographique continue depuis des décennies.", "Approches innovantes en matière de développement urbain.", "Multiples opportunités d'activités de plein air.", "Engagement en faveur de projets de durabilité écologique."],
