      hu: ["Magában foglalja a Sawtooth-hegységet.", "Több mint 1000 tó található az erdő területén.", "Népszerű hátizsákos túrákhoz és hegymászáshoz.", "Változatos táj a hegyektől a zsálya-sztyeppékig."],
      ro: ["Include Munții Sawtooth.", "Peste 1000 de lacuri se găsesc în pădure.", "Populară pentru drumeții cu rucsacul și alpinism.", "Peisaj divers, de la munți la stepe de salvie."],
      en: ["Encompasses the Sawtooth Mountains.", "Over 1,000 lakes are located within the forest.", "Popular for backpacking and mountaineering.", "Diverse landscape from mountains to sagebrush steppe."],
      es: ["Incluye las montañas Sawtooth.", "Más de 1000 lagos se encuentran en la zona forestal.", "Popular para el excursionismo con mochila y el alpinismo.", "Paisaje diverso, desde montañas hasta estepas de artemisa."],
      pt: ["Inclui as montanhas Sawtooth.", "Mais de 1000 lagos situam-se na zona florestal.", "Popular para viagens de mochila e alpinismo.", "Paisagem diversificada, desde montanhas a estepes de artemísia."],
